<!doctype html>
<html lang="de">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>MucLegal · Unterlassungs- und Umsetzungsmonitor</title>
  <style>
    :root {
      color-scheme:light; --background:#f8fafc; --card:#fff; --foreground:#0f172a;
      --muted:#64748b; --muted-bg:#f1f5f9; --border:#e2e8f0; --primary:#0891b2;
      --primary-fg:#fff; --success:#059669; --warning:#d97706; --danger:#dc2626;
      --radius:.62rem; --shadow:0 1px 2px rgb(15 23 42 / .045);
    }
    * { box-sizing:border-box; }
    html,body { width:100%; height:100%; margin:0; overflow:hidden; }
    body { background:var(--background); color:var(--foreground); font:13px/1.4 Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif; }
    button,input,select,textarea { font:inherit; }
    button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible { outline:2px solid color-mix(in srgb,var(--primary) 35%,transparent); outline-offset:2px; }
    .app { height:100dvh; min-height:0; display:grid; grid-template-rows:clamp(54px,7.2vh,66px) minmax(0,1fr); }
    .topbar { display:flex; align-items:center; gap:16px; padding:8px clamp(14px,2vw,28px); background:#fff; border-bottom:1px solid var(--border); }
    .logo { width:clamp(164px,16vw,218px); max-height:45px; object-fit:contain; object-position:left center; }
    .topbar .separator { width:1px; height:28px; background:var(--border); }
    .brand-copy { min-width:0; }
    .brand-copy strong { display:block; font-size:13px; }
    .brand-copy span { color:var(--muted); font-size:11px; }
    .badge { display:inline-flex; align-items:center; gap:5px; width:max-content; border:1px solid var(--border); border-radius:999px; padding:3px 8px; background:#fff; font-size:10px; font-weight:700; letter-spacing:.04em; text-transform:uppercase; white-space:nowrap; }
    .badge::before { content:""; width:6px; height:6px; border-radius:50%; background:var(--primary); }
    .topbar .badge { margin-left:auto; }
    .lab-link { display:inline-flex; align-items:center; min-height:30px; border:1px solid var(--border); border-radius:7px; padding:0 10px; color:var(--foreground); font-size:10px; font-weight:700; text-decoration:none; white-space:nowrap; }
    .lab-link:hover { background:var(--muted-bg); }
    .sidebar-toggle { display:none; }
    .workspace { min-height:0; display:grid; grid-template-columns:minmax(0,1.62fr) minmax(360px,1fr); }
    .control { min-height:0; overflow:hidden; padding:clamp(10px,1.6vh,18px) clamp(12px,1.6vw,24px); display:flex; flex-direction:column; gap:clamp(8px,1.25vh,14px); }
    .control.intake-mode { overflow-y:auto; overscroll-behavior:contain; scrollbar-gutter:stable; }
    .proof { min-height:0; overflow-y:auto; overscroll-behavior:contain; scrollbar-gutter:stable; background:#fff; border-left:1px solid var(--border); }
    .proof-inner { min-height:100%; padding:clamp(12px,1.6vw,22px); }
    .card { border:1px solid var(--border); border-radius:var(--radius); background:var(--card); box-shadow:var(--shadow); }
    .card-pad { padding:clamp(10px,1.4vh,16px); }
    h1,h2,h3,p { margin:0; }
    h1 { font-size:clamp(16px,1.45vw,20px); letter-spacing:-.02em; }
    h2 { font-size:13px; }
    h3 { color:var(--muted); font-size:10px; font-weight:700; letter-spacing:.08em; text-transform:uppercase; }
    .muted { color:var(--muted); }
    .url-head { display:flex; justify-content:space-between; gap:14px; align-items:flex-start; }
    .url-head p { margin-top:2px; max-width:670px; font-size:11px; }
    .url-form { display:grid; grid-template-columns:minmax(0,1fr) auto; gap:8px; margin-top:10px; }
    .tenor-panel summary { cursor:pointer; font-weight:700; }
    .tenor-grid { display:grid; grid-template-columns:1fr 1fr; gap:7px; margin-top:9px; }
    .tenor-grid .wide { grid-column:1/-1; }
