    .input,.select { height:36px; width:100%; border:1px solid var(--border); border-radius:calc(var(--radius) - 2px); background:#fff; color:var(--foreground); padding:0 10px; box-shadow:0 1px 1px rgb(15 23 42 / .03); }
    .button { height:36px; border:1px solid var(--border); border-radius:calc(var(--radius) - 2px); background:#fff; color:var(--foreground); padding:0 13px; font-weight:650; cursor:pointer; white-space:nowrap; }
    .button:hover { background:var(--muted-bg); }
    .button.primary { border-color:var(--primary); background:var(--primary); color:var(--primary-fg); }
    .button.primary:hover { filter:brightness(.94); }
    .button:disabled { opacity:.45; cursor:not-allowed; }
    .alert { display:flex; gap:8px; align-items:flex-start; margin-top:8px; padding:7px 9px; border:1px solid var(--border); border-radius:calc(var(--radius) - 2px); background:var(--muted-bg); font-size:11px; }
    .alert.warning { border-color:#fed7aa; background:#fff7ed; color:#9a3412; }
    .pipeline-card { padding:clamp(10px,1.25vh,14px); }
    .section-row { display:flex; align-items:center; justify-content:space-between; gap:12px; margin-bottom:9px; }
    .steps { display:grid; grid-template-columns:repeat(8,minmax(0,1fr)); gap:5px; }
    .step { position:relative; min-width:0; border:1px solid var(--border); border-radius:calc(var(--radius) - 2px); background:#fff; padding:7px 5px; text-align:center; color:var(--muted); }
    .step-dot { display:block; width:7px; height:7px; margin:0 auto 4px; border:1px solid #94a3b8; border-radius:50%; background:#fff; }
    .step-name { display:block; overflow:hidden; font-size:10px; font-weight:650; text-overflow:ellipsis; white-space:nowrap; }
    .step-state { display:block; margin-top:1px; font-size:9px; }
    .step[data-state=active] { border-color:#67e8f9; background:#ecfeff; color:#0e7490; }
    .step[data-state=active] .step-dot { border-color:var(--primary); background:var(--primary); box-shadow:0 0 0 3px #cffafe; }
    .step[data-state=success] { border-color:#a7f3d0; background:#ecfdf5; color:#047857; }
    .step[data-state=success] .step-dot { border-color:var(--success); background:var(--success); }
    .step[data-state=skipped] { border-style:dashed; opacity:.7; }
    .step[data-state=warning] { border-color:#fed7aa; background:#fff7ed; color:#b45309; }
    .step[data-state=warning] .step-dot { border-color:var(--warning); background:var(--warning); }
    .step[data-state=failed] { border-color:#fecaca; background:#fef2f2; color:#b91c1c; }
    .step[data-state=failed] .step-dot { border-color:var(--danger); background:var(--danger); }
    .run-status { min-height:30px; display:flex; align-items:center; gap:8px; margin-top:8px; padding:6px 8px; border-top:1px solid var(--border); color:var(--muted); font-size:11px; }
    .run-status strong { color:var(--foreground); }
    .tech-grid { min-height:0; flex:1; display:grid; grid-template-columns:1fr 1fr; gap:clamp(8px,1.2vh,12px); }
    .metric-card { min-height:0; padding:clamp(10px,1.25vh,14px); overflow:hidden; }
    .metric-head { display:flex; justify-content:space-between; align-items:center; padding-bottom:8px; border-bottom:1px solid var(--border); }
    .metric-list { display:grid; gap:clamp(6px,1vh,10px); padding-top:9px; }
    .metric { display:grid; grid-template-columns:minmax(96px,.7fr) minmax(0,1.3fr); gap:8px; align-items:start; }
    .metric dt { color:var(--muted); }
    .metric dd { margin:0; min-width:0; font-weight:650; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
    .metric code { font:10px/1.4 ui-monospace,SFMono-Regular,Consolas,monospace; }
    .status-chip { display:inline-flex; align-items:center; border-radius:999px; padding:2px 7px; background:var(--muted-bg); font-size:10px; font-weight:700; }
    .status-chip.ok { background:#ecfdf5; color:#047857; }
    .status-chip.warn { background:#fff7ed; color:#b45309; }
    .review { display:flex; align-items:center; gap:10px; padding:clamp(8px,1vh,11px) clamp(10px,1.2vw,14px); }
    .review-copy { min-width:150px; margin-right:auto; }
    .review-copy p { font-size:10px; color:var(--muted); }
    .review form { display:flex; gap:6px; }
    .review .button { height:30px; padding:0 9px; font-size:10px; }
    .proof-head { position:sticky; top:0; z-index:3; margin:-1px -1px 0; padding:0 1px 12px; background:#fff; }
    .proof-title { display:flex; align-items:flex-start; justify-content:space-between; gap:12px; }
    .proof-title p { margin-top:2px; font-size:11px; color:var(--muted); }
    .selectors { display:grid; grid-template-columns:1fr 1fr; gap:7px; margin-top:10px; }
    .select { height:34px; font-size:11px; }
    .proof-summary { margin-bottom:12px; padding:10px; background:var(--muted-bg); box-shadow:none; }
    .summary-url { overflow:hidden; margin-bottom:8px; font-size:11px; font-weight:650; text-overflow:ellipsis; white-space:nowrap; }
    .summary-grid { display:grid; grid-template-columns:1fr 1fr; gap:5px 10px; font-size:10px; }
    .summary-grid span { color:var(--muted); }
    .summary-grid strong { display:block; overflow:hidden; color:var(--foreground); text-overflow:ellipsis; white-space:nowrap; }
    .artifact-group { margin-top:12px; }
    .artifact-group h3 { margin-bottom:6px; }
    .artifact-list { display:grid; grid-template-columns:1fr 1fr; gap:5px; }
    .artifact { display:flex; align-items:center; gap:7px; min-width:0; border:1px solid var(--border); border-radius:calc(var(--radius) - 3px); background:#fff; padding:7px 8px; color:var(--foreground); text-align:left; cursor:pointer; }
    .artifact:hover:not(:disabled),.artifact.selected { border-color:#67e8f9; background:#ecfeff; }
    .artifact:disabled { color:#94a3b8; background:#f8fafc; cursor:default; }
    .artifact-mark { flex:0 0 auto; width:7px; height:7px; border-radius:50%; background:var(--success); }
    .artifact:disabled .artifact-mark { background:#cbd5e1; }
    .artifact span:last-child { overflow:hidden; font-size:10px; font-weight:650; text-overflow:ellipsis; white-space:nowrap; }
    .preview { margin-top:12px; overflow:hidden; }
    .preview-bar { display:flex; align-items:center; gap:8px; min-height:34px; padding:7px 9px; border-bottom:1px solid var(--border); }
    .preview-bar strong { overflow:hidden; margin-right:auto; font-size:10px; text-overflow:ellipsis; white-space:nowrap; }
    .preview-bar a { color:var(--primary); font-size:10px; font-weight:650; text-decoration:none; }
    .preview-empty { display:grid; min-height:150px; place-items:center; padding:20px; color:var(--muted); text-align:center; }
    pre { max-height:330px; min-height:150px; margin:0; overflow:auto; padding:11px; background:#0f172a; color:#dbeafe; font:10px/1.55 ui-monospace,SFMono-Regular,Consolas,monospace; white-space:pre-wrap; word-break:break-word; }
    .pdf-frame { width:100%; height:430px; border:0; background:var(--muted-bg); }
    .image-preview { display:block; width:100%; max-height:520px; object-fit:contain; background:var(--muted-bg); }
    [hidden] { display:none !important; }
    @media (max-height:800px) {
      .brand-copy span,.url-head p { display:none; }
      .control { gap:7px; padding-top:8px; padding-bottom:8px; }
      .card-pad,.pipeline-card,.metric-card { padding:9px; }
      .url-form { margin-top:7px; }
      .alert { margin-top:6px; padding:5px 8px; }
      .step { padding:5px 3px; }
      .metric-list { gap:5px; padding-top:6px; }
      .review { padding-top:6px; padding-bottom:6px; }
    }
    @media (max-width:1023px) {
      .workspace { display:block; }
      .control { height:100%; }
      .proof { position:fixed; z-index:20; inset:clamp(54px,7.2vh,66px) 0 0 auto; width:min(92vw,480px); border-left:1px solid var(--border); box-shadow:-16px 0 40px rgb(15 23 42 / .16); transform:translateX(102%); transition:transform .2s ease; }
      .proof.open { transform:translateX(0); }
      .sidebar-toggle { display:inline-flex; }
    }
  </style>
</head>
<body>
<div class="app">
  <header class="topbar">
    {% if workflow_enabled %}<img class="logo" src="/static/muclegal-logo-light.png" alt="MucLegal">{% else %}<strong>MucLegal</strong>{% endif %}
